import "@stdlib/gas-payments"
import "errors"
import "messages"
import "order-helpers"
import "order-state"
import "storage"
import "types"

contract Multisig {
    author: "The Tolk Team"
    version: "2.1"
    description: "Multisig V2.1. Multi-signature wallet with order-based approval"
    incomingMessages: AllowedMessageToMultisig
    storage: MultisigStorage
}

type AllowedOrderAction = SendMessageAction | UpdateMultisigParamsAction

@inline
fun executeOrder(mutate storage: MultisigStorage, orderBody: DirectOrderActionsMap): bool {
    // rare use of ACCEPT outside of external msg,
    // goal is to assure we have exactly max gas amount to process actions
    setGasLimitToMaximum();

    var isStorageUpdated = false;

    var actionLookup = orderBody.findFirst();
    while (actionLookup.isFound) {
        val actionCell = actionLookup.loadValue();
        val action = lazy AllowedOrderAction.fromCell(actionCell);

        match (action) {
            SendMessageAction => {
                sendRawMessage(action.message, action.mode);
            }

            UpdateMultisigParamsAction => {
                val signersNum = validateDictionarySequence(action.signers);

                assert (signersNum >= 1) throw ERROR_INVALID_SIGNERS;
                assert (action.threshold > 0) throw ERROR_INVALID_THRESHOLD;
                assert (action.threshold <= signersNum) throw ERROR_INVALID_THRESHOLD;

                validateDictionarySequence(action.proposers);

                storage.threshold = action.threshold;
                storage.signers = action.signers;
                storage.signersNum = signersNum;
                storage.proposers = action.proposers;
                isStorageUpdated = true;
            }

            else => {
                // keep FunC behavior: ignore unknown action opcodes
            }
        }

        actionLookup = orderBody.iterateNext(actionLookup);
    }

    return isStorageUpdated;
}

type AllowedMessageToMultisig =
    | NewOrderRequest
    | ExecuteOrderRequest
    | ExecuteInternalRequest
    | TextComment

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToMultisig.fromSlice(in.body);

    match (msg) {
        NewOrderRequest => {
            var storage = lazy MultisigStorage.load();
            var orderSeqno = msg.orderSeqno;

            if (!storage.allowArbitraryOrderSeqno) {
                if (orderSeqno == MAX_ORDER_SEQNO) {
                    orderSeqno = storage.nextOrderSeqno;
                } else {
                    assert (orderSeqno == storage.nextOrderSeqno) throw ERROR_INVALID_NEW_ORDER;
                }
                storage.nextOrderSeqno += 1;
            }

            val signerOrProposer: map<uint8, address> = msg.isAutoApprove
                ? storage.signers
                : storage.proposers;
            val expectedSender = signerOrProposer.get(msg.index);

            assert (expectedSender.isFound) throw ERROR_UNAUTHORIZED_NEW_ORDER;
            assert (
                in.senderAddress == expectedSender.loadValue()
            ) throw ERROR_UNAUTHORIZED_NEW_ORDER;

            val now = blockchain.now();

            assert (msg.expirationDate >= now) throw ERROR_EXPIRED;

            val minimalValue = calculateOrderProcessingCost(
                msg.order,
                storage.signers,
                msg.expirationDate - now,
            );
            assert (in.valueCoins >= minimalValue) throw ERROR_NOT_ENOUGH_TON;

            val signerIndexOnInit: SignerIndexOnInit = msg.isAutoApprove ? msg.index : null;

            val deployOrderMsg = createMessage({
                bounce: true,
                dest: calculateOrderStateInit(contract.getAddress(), orderSeqno),
                value: 0,
                body: InitOrderRequest {
                    queryId: msg.queryId,
                    threshold: storage.threshold,
                    signers: storage.signers,
                    expirationDate: msg.expirationDate,
                    order: msg.order,
                    signerIndexOnInit,
                },
            });
            deployOrderMsg.send(
                SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL,
            );

            storage.save();
        }

        ExecuteOrderRequest => {
            var storage = lazy MultisigStorage.load();
            val expectedOrderAddress = calculateOrderAddress(contract.getAddress(), msg.orderSeqno);

            assert (in.senderAddress == expectedOrderAddress) throw ERROR_UNAUTHORIZED_EXECUTE;
            assert (
                msg.signersHash == storage.signers.hashCell() &&
                msg.approvalsNum >= storage.threshold
            ) throw ERROR_SIGNERS_OUTDATED;
            assert (msg.expirationDate >= blockchain.now()) throw ERROR_EXPIRED;

            if (executeOrder(mutate storage, msg.order)) {
                storage.save();
            }
        }

        ExecuteInternalRequest => {
            var storage = lazy MultisigStorage.load();
            assert (in.senderAddress == contract.getAddress()) throw ERROR_UNAUTHORIZED_EXECUTE;
            if (executeOrder(mutate storage, msg.order)) {
                storage.save();
            }
        }

        TextComment => {}

        else => {}
    }
}

get fun get_multisig_data(): MultisigDataReply {
    val storage = lazy MultisigStorage.load();

    val signersNum = validateDictionarySequence(storage.signers);
    assert (signersNum == storage.signersNum) throw ERROR_INCONSISTENT_DATA;

    validateDictionarySequence(storage.proposers);

    assert (signersNum >= 1) throw ERROR_INVALID_SIGNERS;
    assert (storage.threshold > 0) throw ERROR_INVALID_THRESHOLD;
    assert (storage.threshold <= signersNum) throw ERROR_INVALID_THRESHOLD;

    return {
        nextOrderSeqno: storage.allowArbitraryOrderSeqno ? -1 : storage.nextOrderSeqno,
        threshold: storage.threshold,
        signers: storage.signers.toLowLevelDict()!,
        proposers: storage.proposers.toLowLevelDict(),
    };
}

get fun get_order_estimate(order: cell, expirationDate: int): int {
    val storage = lazy MultisigStorage.load();
    val orderBody = createMapFromLowLevelDict<uint8, cell>(order);

    return calculateOrderProcessingCost(
        orderBody,
        storage.signers,
        expirationDate - blockchain.now(),
    );
}

get fun get_order_address(orderSeqno: int): address {
    return calculateOrderAddress(contract.getAddress(), orderSeqno);
}

const COMMENT_APPROVE = "approve".literalSlice()

struct (0x00000000) TextComment {
    comment: RemainingBitsAndRefs
}

type IndexedAddressMap = map<uint8, address>

type DirectIndexedAddressMap = map<uint8, address>

type DirectOrderActionsMap = map<uint8, cell>

// if signer wants to approve, he will provide his index;
// just false otherwise
type SignerIndexOnInit = uint8?

struct (0xf1381e5b) SendMessageAction {
    mode: uint8
    message: cell
}

struct (0x1d0cfbd3) UpdateMultisigParamsAction {
    threshold: uint8
    signers: DirectIndexedAddressMap
    proposers: IndexedAddressMap
}

struct (0xf718510f) NewOrderRequest {
    queryId: uint64
    orderSeqno: uint256
    isAutoApprove: bool
    index: uint8
    expirationDate: uint48
    order: DirectOrderActionsMap
}

struct (0x75097f5d) ExecuteOrderRequest {
    queryId: uint64
    orderSeqno: uint256
    expirationDate: uint48
    approvalsNum: uint8
    signersHash: uint256
    order: DirectOrderActionsMap
}

struct (0xa32c59bf) ExecuteInternalRequest {
    queryId: uint64
    order: DirectOrderActionsMap
}

struct (0x9c73fba2) InitOrderRequest {
    queryId: uint64
    threshold: uint8
    signers: DirectIndexedAddressMap
    expirationDate: uint48
    order: DirectOrderActionsMap
    signerIndexOnInit: SignerIndexOnInit
}

struct (0xa762230f) ApproveRequest {
    queryId: uint64
    signerIndex: uint8
}

struct (0x82609bf6) ApproveAccepted {
    queryId: uint64
}

struct (0xafaf283e) ApproveRejected {
    queryId: uint64
    exitCode: uint32
}

import "@stdlib/gas-payments"
import "errors"
import "messages"
import "storage"
import "types"

const MULTISIG_INIT_ORDER_GAS = 10232
const ORDER_INIT_GAS = 4614
const ORDER_EXECUTE_GAS = 11244
const MULTISIG_EXECUTE_GAS = 7576

const INIT_ORDER_BIT_OVERHEAD = 1337
const INIT_ORDER_CELL_OVERHEAD = 6
const ORDER_STATE_BIT_OVERHEAD = 1760
const ORDER_STATE_CELL_OVERHEAD = 6
const EXECUTE_ORDER_BIT_OVERHEAD = 664
const EXECUTE_ORDER_CELL_OVERHEAD = 1

fun calculateOrderProcessingCost(
    orderBody: DirectOrderActionsMap,
    signers: DirectIndexedAddressMap,
    duration: int,
): coins {
    val orderDict = orderBody.toLowLevelDict()!;
    val signersDict = signers.toLowLevelDict()!;

    val gasBefore = getGasConsumedAtTheMoment();

    val (orderCells, orderBits, _) = orderDict.calculateSizeStrict(8192);
    val (signersCells, signersBits, _) = signersDict.calculateSizeStrict(512);

    val sizeCountingGas = getGasConsumedAtTheMoment() - gasBefore;

    val gasFees = calculateGasFee(BASECHAIN, MULTISIG_INIT_ORDER_GAS + sizeCountingGas) +
    calculateGasFee(BASECHAIN, ORDER_INIT_GAS) +
    calculateGasFee(BASECHAIN, ORDER_EXECUTE_GAS) +
    calculateGasFee(BASECHAIN, MULTISIG_EXECUTE_GAS);

    val forwardFees = calculateForwardFee(
        BASECHAIN,
        INIT_ORDER_BIT_OVERHEAD + orderBits + signersBits,
        INIT_ORDER_CELL_OVERHEAD + orderCells + signersCells,
    ) +
    calculateForwardFee(
        BASECHAIN,
        EXECUTE_ORDER_BIT_OVERHEAD + orderBits,
        EXECUTE_ORDER_CELL_OVERHEAD + orderCells,
    );

    val storageFees = calculateStorageFee(
        BASECHAIN,
        duration,
        ORDER_STATE_BIT_OVERHEAD + orderBits + signersBits,
        ORDER_STATE_CELL_OVERHEAD + orderCells + signersCells,
    );

    return gasFees + forwardFees + storageFees;
}

fun getTextComment(inMsgBody: RemainingBitsAndRefs): slice {
    var result = beginCell();

    result.storeSlice(inMsgBody.preloadBits(inMsgBody.remainingBitsCount()));

    repeat (inMsgBody.depth()) {
        inMsgBody = inMsgBody.preloadRef().beginParse();
        result.storeSlice(inMsgBody.preloadBits(inMsgBody.remainingBitsCount()));
    }

    return result.toSlice();
}

fun DirectIndexedAddressMap.findSignerByAddress(self, signerAddress: address): (uint8, bool) {
    var signerIndex: uint8 = 0;
    var foundSigner = false;

    var item = self.findFirst();
    while (item.isFound && !foundSigner) {
        val currentAddress = item.loadValue();
        if (currentAddress == signerAddress) {
            signerIndex = item.getKey();
            foundSigner = true;
        } else {
            item = self.iterateNext(item);
        }
    }

    return (signerIndex, foundSigner);
}

fun OrderStorageInitialized.addApproval(mutate self, signerIndex: uint8) {
    val mask = (1 << signerIndex);

    assert ((self.remaining.approvalsMask & mask) == 0) throw ERROR_ALREADY_APPROVED;

    self.remaining.approvalsNum += 1;
    self.remaining.approvalsMask |= mask;
}

fun OrderStorageInitialized.tryExecute(mutate self, queryId: uint64) {
    if (self.remaining.approvalsNum == self.remaining.threshold) {
        val executeMsg = createMessage({
            bounce: false,
            dest: self.multisigAddress,
            value: 0,
            body: ExecuteOrderRequest {
                queryId,
                orderSeqno: self.orderSeqno,
                expirationDate: self.remaining.expirationDate,
                approvalsNum: self.remaining.approvalsNum,
                signersHash: self.remaining.signers.hashCell(),
                order: self.remaining.order,
            },
        });
        // SAFETY: if we execute, we want order to be drained empty
        executeMsg.send(SEND_MODE_CARRY_ALL_BALANCE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);

        self.remaining.sentForExecution = true;
    }
}

@inline
fun sendApproveRejected(responseAddress: address, queryId: uint64, exitCode: uint32) {
    val rejectedMsg = createMessage({
        bounce: false,
        dest: responseAddress,
        value: 0,
        body: ApproveRejected { queryId, exitCode },
    });
    rejectedMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);
}

@inline_ref
fun OrderStorageInitialized.approve(
    mutate self,
    signerIndex: uint8,
    responseAddress: address,
    queryId: uint64,
) {
    if (self.remaining.sentForExecution) {
        sendApproveRejected(responseAddress, queryId, ERROR_ALREADY_EXECUTED);
        return;
    }

    val mask = (1 << signerIndex);
    if ((self.remaining.approvalsMask & mask) != 0) {
        sendApproveRejected(responseAddress, queryId, ERROR_ALREADY_APPROVED);
        return;
    }

    self.remaining.approvalsNum += 1;
    self.remaining.approvalsMask |= mask;

    val acceptMsg = createMessage({
        bounce: false,
        dest: responseAddress,
        value: 0,
        body: ApproveAccepted { queryId },
    });
    acceptMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_BOUNCE_ON_ACTION_FAIL);

    self.tryExecute(queryId);
    self.save();
}

import "../../gen/Order.code"

struct OrderInitData {
    multisigAddress: address
    orderSeqno: uint256
}

fun getOrderCodeAsLibraryReference(): cell {
    return orderCompiledCodeLibraryRef();
}

fun calculateOrderStateInit(multisigAddress: address, orderSeqno: uint256): AutoDeployAddress {
    return {
        stateInit: ContractState {
            code: getOrderCodeAsLibraryReference(),
            data: OrderInitData { multisigAddress, orderSeqno }.toCell(),
        },
        workchain: BASECHAIN,
    };
}

fun calculateOrderAddress(multisigAddress: address, orderSeqno: uint256): address {
    return calculateOrderStateInit(multisigAddress, orderSeqno).calculateAddress();
}

import "messages"

struct MultisigStorage {
    nextOrderSeqno: uint256
    threshold: uint8
    signers: DirectIndexedAddressMap
    signersNum: uint8
    proposers: IndexedAddressMap
    allowArbitraryOrderSeqno: bool
}

fun MultisigStorage.load(): MultisigStorage {
    return MultisigStorage.fromCell(contract.getData());
}

fun MultisigStorage.save(self) {
    contract.setData(self.toCell());
}

struct OrderStorageInitialized {
    multisigAddress: address
    orderSeqno: uint256
    remaining: OrderStorageRemaining
}

struct OrderStorageRemaining {
    threshold: uint8
    sentForExecution: bool
    signers: DirectIndexedAddressMap
    approvalsMask: uint256
    approvalsNum: uint8
    expirationDate: uint48
    order: DirectOrderActionsMap
}

struct MultisigDataReply {
    nextOrderSeqno: int
    threshold: int
    signers: dict
    proposers: dict
}

struct OrderDataReply {
    multisigAddress: address
    orderSeqno: int
    threshold: int?
    sentForExecution: bool?
    signers: dict
    approvalsMask: int?
    approvalsNum: int?
    expirationDate: int?
    order: dict
}

fun OrderStorageInitialized.save(self) {
    contract.setData(self.toCell());
}

struct OrderStorageMaybeNotInitialized {
    contractData: slice
}

fun startLoadingOrderStorage(): OrderStorageMaybeNotInitialized {
    return { contractData: contract.getData().beginParse() };
}

struct OrderStorageHeader {
    multisigAddress: address
    orderSeqno: uint256
    remaining: RemainingBitsAndRefs
}

fun OrderStorageMaybeNotInitialized.loadHeader(self): OrderStorageHeader {
    return OrderStorageHeader.fromSlice(self.contractData);
}

fun OrderStorageHeader.isInitialized(self): bool {
    return self.remaining.remainingBitsCount() > 0;
}

fun OrderStorageHeader.loadInitialized(self): OrderStorageInitialized {
    val remaining = OrderStorageRemaining.fromSlice(self.remaining);

    return {
        multisigAddress: self.multisigAddress,
        orderSeqno: self.orderSeqno,
        remaining,
    };
}

import "errors"
import "messages"

const MAX_ORDER_SEQNO = 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff

fun DirectIndexedAddressMap.packToBuilder(self, mutate b: builder) {
    val dictRoot = self.toLowLevelDict();
    b.storeRef(dictRoot!);
}

fun DirectIndexedAddressMap.unpackFromSlice(mutate s: slice): DirectIndexedAddressMap {
    return createMapFromLowLevelDict<uint8, address>(s.loadRef());
}

fun DirectOrderActionsMap.packToBuilder(self, mutate b: builder) {
    val dictRoot = self.toLowLevelDict();
    b.storeRef(dictRoot!);
}

fun DirectOrderActionsMap.unpackFromSlice(mutate s: slice): DirectOrderActionsMap {
    return createMapFromLowLevelDict<uint8, cell>(s.loadRef());
}

@inline
fun validateDictionarySequence<T>(m: map<uint8, T>): int {
    var expectedIndex = 0;

    var item = m.findFirst();
    while (item.isFound) {
        assert (item.getKey() == expectedIndex) throw ERROR_INVALID_DICTIONARY_SEQUENCE;
        expectedIndex += 1;
        item = m.iterateNext(item);
    }

    return expectedIndex;
}

fun DirectIndexedAddressMap.hashCell(self): uint256 {
    return self.toLowLevelDict()!.hash();
}

fun DirectOrderActionsMap.hashCell(self): uint256 {
    return self.toLowLevelDict()!.hash();
}

